import json,re
from pathlib import Path
from genlayer_py import create_client,create_account
from genlayer_py.chains import studionet
ROOT=Path(__file__).parents[1];env=(ROOT.parents[3]/'accounts.env').read_text();key=re.search(r'^ACCOUNT_1_GENLAYER_PRIVATE_KEY\s*=\s*"?([^"\r\n]+)',env,re.M).group(1).strip();client=create_client(chain=studionet,account=create_account(account_private_key=key));tx=client.deploy_contract(code=(ROOT/'contracts'/'contract.py').read_text(),args=[]);print('deploy_tx='+str(tx),flush=True);receipt=client.wait_for_transaction_receipt(transaction_hash=tx,status='FINALIZED',retries=180,interval=5000,full_transaction=True);leader=(receipt.get('consensus_data',{}).get('leader_receipt') or [{}])[0];address=receipt.get('data',{}).get('contract_address') or receipt.get('to_address') or receipt.get('recipient');assert receipt.get('status_name')=='FINALIZED' and str(receipt.get('result_name')).upper()=='MAJORITY_AGREE' and str(leader.get('execution_result')).upper()=='SUCCESS';print(json.dumps({'contract':address,'deploymentTx':str(tx),'status':receipt.get('status_name'),'consensus':receipt.get('result_name'),'execution':leader.get('execution_result')},default=str),flush=True)
